"""Отчёты по остаткам и движению. Только чтение, ничего не меняют."""

from __future__ import annotations

import csv
import io
import logging
from dataclasses import dataclass
from datetime import datetime

from .events import EventLog
from .inventory import Inventory

logger = logging.getLogger(__name__)


@dataclass(frozen=True)
class Movement:
    """Сводка движения по SKU за период."""

    sku: str
    received: int = 0
    issued: int = 0
    adjusted: int = 0

    @property
    def net(self) -> int:
        return self.received - self.issued + self.adjusted


def stock_report(inventory: Inventory, warehouse: str | None = None) -> str:
    """Текстовая таблица физических остатков."""
    levels = inventory.stock_levels(warehouse)
    if not levels:
        return "(no stock)"
    rows = [("WAREHOUSE", "SKU", "NAME", "ON HAND")]
    for level in levels:
        sku = inventory.get_sku(level.sku)
        rows.append((level.warehouse, level.sku, sku.name, f"{level.on_hand} {sku.unit}"))
    widths = [max(len(row[i]) for row in rows) for i in range(4)]
    lines = []
    for row in rows:
        cells = [row[i].ljust(widths[i]) for i in range(3)] + [row[3].rjust(widths[3])]
        lines.append("  ".join(cells).rstrip())
    return "\n".join(lines)


def stock_csv(inventory: Inventory) -> str:
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["warehouse", "sku", "on_hand"])
    for level in inventory.stock_levels():
        writer.writerow([level.warehouse, level.sku, level.on_hand])
    return buffer.getvalue()


def low_stock(inventory: Inventory, threshold: int) -> list[tuple[str, str, int]]:
    """Позиции, физический остаток которых ниже порога (нулевые не попадают)."""
    return [
        (level.warehouse, level.sku, level.on_hand)
        for level in inventory.stock_levels()
        if level.on_hand < threshold
    ]


def movement_summary(
    log: EventLog, since: datetime | None = None, until: datetime | None = None
) -> dict[str, Movement]:
    """Приход/расход/корректировки по SKU за полуинтервал ``[since, until)``.

    Перемещения между складами в сводку не входят: для компании в целом
    это не движение товара.
    """
    totals: dict[str, dict[str, int]] = {}
    for event in log:
        if since is not None and event.ts < since:
            continue
        if until is not None and event.ts >= until:
            continue
        sku = event.get("sku")
        if sku is None:
            continue
        bucket = totals.setdefault(sku, {"received": 0, "issued": 0, "adjusted": 0})
        if event.kind == "RECEIVE":
            bucket["received"] += int(event.fields["qty"])
        elif event.kind == "ISSUE":
            bucket["issued"] += int(event.fields["qty"])
        elif event.kind == "ADJUST":
            bucket["adjusted"] += int(event.fields["delta"])
    logger.debug("movement summary for %d SKUs", len(totals))
    return {sku: Movement(sku=sku, **values) for sku, values in sorted(totals.items())}

"""Командная строка: прогон сценария операций из JSON и вывод отчёта.

Пример сценария::

    [
      {"op": "register", "sku": "BOLT-M8", "name": "Болт М8"},
      {"op": "receive", "wh": "MAIN", "sku": "BOLT-M8", "qty": 100},
      {"op": "issue", "wh": "MAIN", "sku": "BOLT-M8", "qty": 5, "ref": "SO-1"}
    ]

Запуск: ``python -m warehouse.cli run scenario.json --show log``.
"""

from __future__ import annotations

import argparse
import json
import logging
import sys
from pathlib import Path
from typing import Any, Sequence, TextIO

from . import reports
from .errors import WarehouseError
from .inventory import Inventory

logger = logging.getLogger(__name__)


def apply_operation(inventory: Inventory, op: dict[str, Any]) -> None:
    kind = op.get("op")
    if kind == "register":
        inventory.register_sku(op["sku"], op.get("name", op["sku"]), op.get("unit", "pcs"))
    elif kind == "receive":
        inventory.receive(op["wh"], op["sku"], op["qty"], op.get("ref"))
    elif kind == "issue":
        inventory.issue(op["wh"], op["sku"], op["qty"], op.get("ref"))
    elif kind == "transfer":
        inventory.transfer(op["src"], op["dst"], op["sku"], op["qty"], op.get("ref"))
    elif kind == "adjust":
        inventory.adjust(op["wh"], op["sku"], op["counted"], op["reason"])
    else:
        raise WarehouseError(f"unknown operation {kind!r}")


def run_scenario(operations: list[dict[str, Any]], inventory: Inventory | None = None) -> Inventory:
    inventory = inventory if inventory is not None else Inventory()
    for index, op in enumerate(operations, start=1):
        try:
            apply_operation(inventory, op)
        except KeyError as exc:
            raise WarehouseError(f"operation #{index}: missing field {exc.args[0]!r}") from exc
        except WarehouseError as exc:
            raise WarehouseError(f"operation #{index}: {exc}") from exc
    return inventory


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="warehouse")
    sub = parser.add_subparsers(dest="command", required=True)
    run = sub.add_parser("run", help="apply a JSON scenario and print a report")
    run.add_argument("scenario", type=Path)
    run.add_argument("--show", choices=["stock", "csv", "log", "movement"], default="stock")
    run.add_argument("--warehouse", default=None)
    run.add_argument("-v", "--verbose", action="store_true")
    return parser


def main(argv: Sequence[str] | None = None, out: TextIO | None = None) -> int:
    out = out if out is not None else sys.stdout
    args = build_parser().parse_args(argv)
    logging.basicConfig(level=logging.DEBUG if args.verbose else logging.WARNING)
    try:
        operations = json.loads(args.scenario.read_text(encoding="utf-8"))
        inventory = run_scenario(operations)
    except (OSError, ValueError, WarehouseError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    if args.show == "stock":
        print(reports.stock_report(inventory, args.warehouse), file=out)
    elif args.show == "csv":
        print(reports.stock_csv(inventory), end="", file=out)
    elif args.show == "log":
        for line in inventory.log.lines():
            print(line, file=out)
    else:
        for movement in reports.movement_summary(inventory.log).values():
            print(
                f"{movement.sku}: +{movement.received} -{movement.issued} "
                f"adj {movement.adjusted:+d} net {movement.net:+d}",
                file=out,
            )
    return 0


if __name__ == "__main__":  # pragma: no cover
    raise SystemExit(main())

